static string Umkehren(string s)
{
    if (s.Length <= 1) return s;
    return Umkehren(s.Substring(1)) + s[0];
}

Console.WriteLine(Umkehren("HTL"));

static void P(int n)
{
    if (n == 0) return;
    Console.Write(n);
    P(n - 1);
    Console.Write(n);
}

P(3);

static int Z(int n)
{
    if (n == 0) return 0;
    return 1 + Z(n - 2);
}

Console.WriteLine(Z(5));

static int Q(int n, int s = 0)
{
    if (n == 0) return s;
    return Q(n / 10, s + n % 10);
}

Console.WriteLine(Q(2026));

static long P(long x, int n)
{
    if (n == 0) return 1;
    if (n % 2 == 1)
        return x * P(x, n - 1);
    return P(x, n / 2) * P(x, n / 2);
}

static int A(int n)
{
    if (n < 2) return n;
    return A(n / 2) + n % 2;
}

Console.WriteLine(A(13));
